  const id = (ch) => ch.charCodeAt(0) - 97;
  const same = Array.from({ length: 26 }, (_, i) => Array.from({ length: 26 }, (_, j) => i === j));
  for (const e of equations) if (e[1] === '=') { same[id(e[0])][id(e[3])] = true; same[id(e[3])][id(e[0])] = true; }
  for (let k = 0; k < 26; k++)
    for (let i = 0; i < 26; i++)
      for (let j = 0; j < 26; j++) if (same[i][k] && same[k][j]) same[i][j] = true;
  return equations.every((e) => e[1] === '=' || !same[id(e[0])][id(e[3])]);
}

